import json, sys
d = json.load(sys.stdin)
ti = d.get('tool_input', {})
tn = d.get('tool_name', '')
texts = []
if tn == 'Write':
    texts.append(ti.get('content', ''))
elif tn == 'Edit':
    texts.append(ti.get('new_string', ''))
elif tn == 'MultiEdit':
    for e in ti.get('edits', []) or []:
        texts.append(e.get('new_string', ''))
EM = chr(0x2014); EN = chr(0x2013)
bad = []
for t in texts:
    if EM in t: bad.append('em dash (U+2014)')
    if EN in t: bad.append('en dash (U+2013)')
if not bad:
    sys.exit(0)
sys.stderr.write('Unicode dash detected in tool input: ' + ', '.join(sorted(set(bad))) + '. Forbidden: U+2013/U+2014. Do not paste ASCII -- as typographic dash in prose; rewrite (colon, semicolon, paren, or split sentences). See CLAUDE.md No Unicode Dashes.')
sys.exit(2)
"

