import json, sys, subprocess, os
d = json.load(sys.stdin)
cmd = d.get('tool_input', {}).get('command', '')
if not cmd.startswith('git commit'):
    sys.exit(0)
try:
    changed = subprocess.check_output(['git', 'show', '--name-only', '--format=', 'HEAD'], text=True).splitlines()
except subprocess.CalledProcessError:
    sys.exit(0)
exts = ('.c', '.h', '.asm', '.ld')
if not any(f.endswith(exts) for f in changed if f):
    sys.exit(0)
root = subprocess.check_output(['git', 'rev-parse', '--show-toplevel']).decode().strip()
# §4 / Codex M2: if HEAD was a SKIP_REVIEW_HOOK opt-out, prepend the
# reason so the user sees in the next turn what was bypassed.
skip_prefix = ''
head = ''
try:
    head = subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=root, text=True, timeout=2, stderr=subprocess.DEVNULL).strip()
except Exception:
    pass
log_path = root + '/.claude/state/skip-log.jsonl'
# SKIP records the parent SHA at SKIP-time (before commit creates the new HEAD), so post-commit lookup must compare against HEAD~1 to find the matching record (Codex M1).
parent = ''
try:
    parent = subprocess.check_output(['git', 'rev-parse', 'HEAD~1'], cwd=root, text=True, timeout=2, stderr=subprocess.DEVNULL).strip()
except Exception:
    pass
if parent and os.path.exists(log_path):
    try:
        with open(log_path, 'r', encoding='utf-8') as f:
            for line in reversed(f.readlines()):
                line = line.strip()
                if not line:
                    continue
                try:
                    rec = json.loads(line)
                except Exception:
                    continue
                if rec.get('head_sha', '').startswith(parent[:12]) and rec.get('reason'):
                    skip_prefix = '[SKIP_REVIEW_HOOK reason: ' + rec['reason'][:160] + '] '
                    break
    except Exception:
        pass
result = subprocess.run(['bash', root + '/scripts/test.sh', 'QUIET=1'], capture_output=True, text=True, timeout=60, env={**os.environ, 'TIMEOUT': '30'})
if result.returncode == 0:
    line = [l for l in result.stdout.splitlines() if 'PASS' in l]
    msg = line[-1].strip() if line else 'Tests passed'
    print(json.dumps({'systemMessage': skip_prefix + '[smoketest] ' + msg}))
else:
    fails = [l for l in result.stdout.splitlines() if 'FAIL' in l]
    msg = fails[-1].strip() if fails else 'Tests failed'
    print(json.dumps({'systemMessage': skip_prefix + '[smoketest] ' + msg, 'continue': True}))
"

