python3 -c "
import json, sys, subprocess, os
d = json.load(sys.stdin)
path = d.get('tool_input', {}).get('file_path', '')
if not path or not path.endswith('.md'):
    sys.exit(0)
p = path.replace(chr(92), '/')
if 'todo/' not in p:
    sys.exit(0)
try:
    root = subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], stderr=subprocess.DEVNULL).decode().strip()
except Exception:
    sys.exit(0)
validator = root + '/scripts/todo-graph/validate.py'
if not os.path.exists(validator):
    sys.exit(0)
try:
    result = subprocess.run(['python3', validator, '--fix-line-numbers', '--write', '--quiet'], cwd=root, capture_output=True, text=True, timeout=15)
except Exception:
    sys.exit(0)
# Success = nothing to fix OR rewrites applied cleanly. --fix-line-numbers exits 1 only on ambiguity.
if result.returncode == 1 and 'ambiguous' in (result.stdout + result.stderr):
    print(json.dumps({'systemMessage': '[todo-graph auto-rewrite] validate.py --fix-line-numbers refused an ambiguous item-name rewrite: ' + (result.stdout + result.stderr).strip().replace(chr(10), ' ')[:200] + '. Disambiguate the stamp parenthetical by hand.'}))
"
